+import type { PluginWidgetProps } from '@gravity-ui/dashkit';
+
+export type MetricWidgetData = {
+  label: string;
+  value: string;
+  trend: string;
+};
+
+export type ChartWidgetData = {
+  title: string;
+  points: Array<{ x: string; y: number }>;
+};
+
+export type StatusWidgetData = {
+  services: Array<{ name: string; state: 'ok' | 'warning' | 'error' }>;
+};
+
+export type WidgetData = MetricWidgetData | ChartWidgetData | StatusWidgetData;
+
+export type WidgetProps = PluginWidgetProps & {
+  data: WidgetData;
+};
+
+function MetricWidget({ data }: WidgetProps) {
+  const { label, value, trend } = data as MetricWidgetData;
+
+  return (
+    <div className=\"dashboard-widget\">
+      <p className=\"dashboard-widget__label\">{label}</p>
+      <p className=\"dashboard-widget__metric\">{value}</p>
+      <p className=\"dashboard-widget__trend\">{trend}</p>
+    </div>
+  );
+}
+
+function ChartWidget({ data }: WidgetProps) {
+  const { title, points } = data as ChartWidgetData;
+  const maxValue = Math.max(...points.map((point) => point.y));
+
+  return (
+    <div className=\"dashboard-widget\">
+      <p className=\"dashboard-widget__label\">{title}</p>
+      <div className=\"dashboard-widget__chart\">
+        {points.map((point) => (
+          <div
+            key={point.x}
+            className=\"dashboard-widget__chart-point\"
+            style={{ height: "'`${(point.y / maxValue) * 100}%` }}
+          >
+            <span>{point.x}</span>
+          </div>
+        ))}
+      </div>
+    </div>
+  );
+}
+
+function StatusWidget({ data }: WidgetProps) {
+  const { services } = data as StatusWidgetData;
+
+  return (
+    <div className="dashboard-widget">
+      <p className="dashboard-widget__label">Service health</p>
+      <ul className="dashboard-widget__status-list">
+        {services.map((service) => (
+          <li key={service.name}>
+            <span className={`dashboard-widget__status dashboard-widget__status_${service.state}`}>
+              {service.state}
+            </span>
+            {service.name}
+          </li>
+        ))}
+      </ul>
+    </div>
+  );
+}
