const widgetPlugins: Record<WidgetType, WidgetPlugin> = {
  metric: {
    type: '"'metric',
    defaultLayout: { w: 6, h: 4 },
    renderer: ({ data }: WidgetProps) => <MetricWidget data={data} />,
  },
  chart: {
