});

const firstConfig: Config = {
  salt: 'dashboard-salt',
  counter: 4,
  items: [
    {
      id: 'revenue',
      type: 'metric',
      namespace: 'default',
      data: { label: 'Выручка', value: '4.8M', trend: '+12% к прошлому месяцу' },
