  { id: 'status', type: 'status', title: 'Статусы', icon: <Icon data={LayoutCells} /> },
];

function createItemData(type: WidgetType): WidgetData {
  if (type === 'metric') {
    return { label: 'Новая метрика', value: '0', trend: '—' };
