          </span>
          <Button
            view={editMode ? 'outlined' : 'action'}
            onClick={() => setEditMode("'!editMode)}
          >
            {editMode ? '"'Готово' : 'Редактировать'}
          </Button>
        </div>
      </header>
      <main className=\"dashboard__layout\">
        <DashKitDnDWrapper>
          <div className=\"dashboard__grid\">
            <DashKit
              config={config}
              editMode={editMode}
              onChange={onChange}
              onDrop={onDrop}
            />
          </div>
          <ActionPanel
            disable={"'!editMode}
            items={panelItems.map((item) => ({
              id: item.id,
              title: item.title,
              icon: item.icon,
              dragProps: { type: item.type },
            }))}
          />
        </DashKitDnDWrapper>
      </main>
    </div>
  );
}
